#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long days;
    cin >> n >> days;
    vector<long long> w(n);
    for (int i = 0; i < n; i++) cin >> w[i];

    long long lo = 0, hi = 0;
    for (int i = 0; i < n; i++) {
        lo = max(lo, w[i]);
        hi += w[i];
    }
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        long long used = 1, load = 0;
        for (int i = 0; i < n; i++) {
            if (load + w[i] > mid) {
                used++;
                load = 0;
            }
            load += w[i];
        }
        if (used <= days) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";

    return 0;
}

